class Solution:
    def bagOfTokensScore(self, tokens: list[int], power: int) -> int:
        best = 0
        def visit(used, available, score):
            nonlocal best
            best = max(best, score)
            for i, token in enumerate(tokens):
                if used & (1 << i):
                    continue
                if available >= token:
                    visit(used | (1 << i), available - token, score + 1)
                if score:
                    visit(used | (1 << i), available + token, score - 1)
        visit(0, power, 0)
        return best
